package timeescape.ui;
import java.awt.*;import java.awt.image.BufferedImage;import java.util.Random;import javax.swing.*;
final class NotebookStyle {
 static final Color INK=new Color(55,40,25),LINE=new Color(153,125,85),PAPER=new Color(233,217,183);
 private static final BufferedImage GRAIN=new BufferedImage(128,128,BufferedImage.TYPE_INT_RGB);
 static {Random r=new Random(40);for(int y=0;y<128;y++)for(int x=0;x<128;x++){int d=r.nextInt(13)-6;GRAIN.setRGB(x,y,new Color(233+d,217+d,183+d).getRGB());}}
 static final BufferedImage PAPER_IMAGE=load("paper.png");
 static BufferedImage load(String name){try(var in=NotebookStyle.class.getResourceAsStream("/assets/images/notebook/"+name)){if(in==null)throw new IllegalStateException(name);return javax.imageio.ImageIO.read(in);}catch(java.io.IOException e){throw new IllegalStateException(e);}}
 static class Paper extends JPanel {
  Paper(){setOpaque(false);}
  protected void paintComponent(Graphics graphics){Graphics2D g=(Graphics2D)graphics.create();LabTheme.quality(g);g.setColor(new Color(0,0,0,110));g.fillRoundRect(4,5,getWidth()-5,getHeight()-6,22,22);g.setClip(new java.awt.geom.RoundRectangle2D.Float(0,0,getWidth()-5,getHeight()-6,20,20));g.drawImage(PAPER_IMAGE,0,0,getWidth()-5,getHeight()-6,null);g.setClip(null);g.setColor(new Color(121,86,42,160));g.drawRoundRect(1,1,getWidth()-7,getHeight()-8,19,19);g.setColor(new Color(255,248,220,110));g.drawRoundRect(5,5,getWidth()-15,getHeight()-16,15,15);g.dispose();super.paintComponent(graphics);}
 }
 static JTextArea text(String value,int size){JTextArea t=new JTextArea(value);t.setFont(GameFonts.body(size));t.setForeground(INK);t.setOpaque(false);t.setEditable(false);t.setFocusable(false);t.setLineWrap(true);t.setWrapStyleWord(true);return t;}
 static JButton button(String label,boolean dark){JButton b=new JButton(label){protected void paintComponent(Graphics graphics){Graphics2D g=(Graphics2D)graphics.create();LabTheme.quality(g);boolean active=getModel().isRollover()||isSelected();g.setColor(dark?(active?new Color(67,54,38):new Color(36,32,27)):active?new Color(108,81,49):new Color(222,203,166));g.fillRoundRect(0,0,getWidth()-1,getHeight()-1,7,7);g.setColor(LINE);g.drawRoundRect(0,0,getWidth()-1,getHeight()-1,7,7);g.setColor(dark||active?new Color(240,225,195):INK);g.setFont(getFont());FontMetrics fm=g.getFontMetrics();if("hamburger".equals(getName())){for(int i=0;i<3;i++)g.fillRoundRect(getWidth()/2-8,getHeight()/2-7+i*6,16,2,2,2);}else g.drawString(getText(),(getWidth()-fm.stringWidth(getText()))/2,(getHeight()-fm.getHeight())/2+fm.getAscent());if(isFocusOwner()){g.setColor(new Color(191,149,81));g.drawRoundRect(3,3,getWidth()-7,getHeight()-7,5,5);}g.dispose();}};b.setFont(GameFonts.button(16));b.setContentAreaFilled(false);b.setBorderPainted(false);b.setFocusPainted(false);b.setOpaque(false);b.setCursor(GameCursors.interact());b.setPreferredSize(new Dimension(110,36));return b;}
 static JScrollPane scroll(JComponent c){JScrollPane s=new JScrollPane(c);s.setOpaque(false);s.getViewport().setOpaque(false);s.setBorder(null);s.setHorizontalScrollBarPolicy(ScrollPaneConstants.HORIZONTAL_SCROLLBAR_NEVER);s.getVerticalScrollBar().setUnitIncrement(24);s.getVerticalScrollBar().setPreferredSize(new Dimension(10,0));s.getVerticalScrollBar().setUI(new javax.swing.plaf.basic.BasicScrollBarUI(){protected void configureScrollBarColors(){thumbColor=LINE;trackColor=PAPER;}protected JButton createDecreaseButton(int o){return zero();}protected JButton createIncreaseButton(int o){return zero();}private JButton zero(){JButton b=new JButton();b.setPreferredSize(new Dimension(0,0));return b;}});return s;}
}
